<script setup lang="ts">
import {computed} from 'vue';
const props=defineProps<{task:any;projectName?:string;showProject?:boolean;permissions:string[];busy?:boolean}>();
const emit=defineEmits(['open','edit','assign','delete','handoff','place','drag']);
const can=(key:string)=>props.permissions.includes('*')||props.permissions.includes(key);
const priority=computed(()=>['Low','Normal','High','Urgent'][props.task.priority??1]);
const logged=computed(()=>Math.max(0,(props.task.timer_logs||[]).reduce((n:number,l:any)=>n+(l.start_time?Math.max(0,(new Date(l.end_time||Date.now()).getTime()-new Date(l.start_time).getTime())/1000):0),0)));
const timeLabel=computed(()=>{const m=Math.floor(logged.value/60);return m>=60?Math.floor(m/60)+'h '+m%60+'m':m+'m';});
const usage=computed(()=>props.task.original_estimate_minutes?Math.round(logged.value/(props.task.original_estimate_minutes*60)*100):null);
const due=computed(()=>props.task.due_date?new Date(props.task.due_date).toLocaleDateString('en-US',{month:'short',day:'2-digit'}):'');
</script>
<template><article class="jira-card" :draggable="can('task-status')&&!busy" @dragstart="emit('drag',task.id)" @dragend="emit('drag',null)" @click="emit('open',task.id)"><div class="d-flex justify-content-between align-items-center"><span class="jira-key">{{(projectName||task.project?.name||task.department?.dept_name||'TSK').slice(0,3).toUpperCase()}}-{{task.id}}</span><details class="pms-kanban-menu" @click.stop><summary aria-label="Issue actions"><i class="ti ti-dots" aria-hidden="true"></i></summary><div><button v-if="can('task-edit')" @click="emit('edit',task.id)"><i class="ti ti-edit" aria-hidden="true"></i>Edit</button><button v-if="can('task-handoff')&&!task.outgoing_handoffs?.length" @click="emit('handoff',task.id)"><i class="ti ti-arrows-exchange" aria-hidden="true"></i>Hand off</button><button v-if="!task.project_id&&can('task-edit')" @click="emit('place',task.id)">Place in project</button><button v-if="can('task-trash')" class="text-danger" @click="emit('delete',task.id)"><i class="ti ti-trash" aria-hidden="true"></i>Delete</button></div></details></div><button class="jira-card-title" @click.stop="emit('open',task.id)">{{task.title}}</button><span v-if="task.incoming_handoff" class="badge bg-label-info mb-2">From {{task.incoming_handoff.source_department?.dept_name||'another team'}}</span><span v-if="task.outgoing_handoffs?.length" class="badge bg-label-success mb-2">Handed off</span><div v-if="showProject" class="mb-2"><span class="badge bg-label-primary">{{task.project?.name||'Department backlog'}}</span><span v-if="task.sprint" class="badge bg-label-secondary ms-1">{{task.sprint.name}}</span></div><div class="pms-kanban-card-meta"><div><span :title="'Priority: '+priority" :aria-label="'Priority: '+priority" :class="['text-secondary','text-info','text-warning','text-danger'][task.priority??1]"><i class="ti" :class="['ti-arrow-down','ti-equal','ti-arrow-up','ti-chevrons-up'][task.priority??1]" aria-hidden="true"></i></span><span v-if="task.subtasks_count||task.subtasks?.length"><i class="ti ti-list-check" aria-hidden="true"></i>{{task.subtasks_count||task.subtasks?.length}}</span><span v-if="task.comments_count"><i class="ti ti-message" aria-hidden="true"></i>{{task.comments_count}}</span><span v-if="task.attachments_count"><i class="ti ti-paperclip" aria-hidden="true"></i>{{task.attachments_count}}</span><span v-if="logged"><i class="ti ti-clock" aria-hidden="true"></i>{{timeLabel}}</span><span v-if="usage!==null" class="badge" :class="usage>100?'bg-label-danger':usage>=80?'bg-label-warning':'bg-label-success'">{{usage}}%</span><span v-if="due" :class="new Date(task.due_date).getTime()<Date.now()&&task.status!=='completed'?'text-danger':''"><i class="ti ti-calendar" aria-hidden="true"></i>{{due}}</span></div><button class="pms-kanban-assignees" :disabled="!can('task-assign')" :aria-label="task.users?.length?'Manage assignees':'Assign employee'" @click.stop="emit('assign',task.id)"><span v-for="u in task.users?.slice(0,3)" :key="u.id" class="jira-avatar" :title="u.name"><img v-if="u.profile_img" :src="u.profile_img" :alt="u.name"><img v-else :src="'/pms-assets/assets/img/user-picture.png'" :alt="u.name"></span><span v-if="!task.users?.length" class="jira-avatar"><i class="ti ti-user-plus" aria-hidden="true"></i></span><small v-if="task.users?.length>3">+{{task.users.length-3}}</small></button></div></article></template>
